/**
 * main.js — self-contained Three.js anatomical oral-cavity scene.
 *
 * No backend. Assets consumed (all generated by tools/, all with provenance):
 *   assets/oral.glb                     surfaces + baked mucosal/kinematic fields
 *   assets/oral_vessels.json            seven tubular systems (Murray radii)
 *   assets/oral_flow.json               flow paths with real v = Q/A per sample
 *   assets/oral_model.json              secretion, mucosa, kinematics, first pass
 *   assets/oral_cavity_expression.json  measured single-cell ADME profile
 *   assets/{geometry,vessel,flow}_report.json   the audits, read in-scene
 *
 * Five views:
 *   organ      the oral bony frame, teeth, tongue, palate and the three gland
 *              pairs, with the jaw articulating
 *   vessels    the three arterial trees, the venous return and the three duct
 *              systems, with particles at their real v = Q/A
 *   motion     chewing and the oral phase of a swallow, with the in-browser
 *              kinematic measurement on screen
 *   section    the mucosal stacks and the lingual papilla at a DECLARED
 *              magnification
 *   molecular  the sublingual-bypass vs swallowed-first-pass comparison, the
 *              polarised mucosal cell and the measured expression bars
 *
 * Public API (also used by the automated probe):
 *   const api = await createOralScene({ container, assetBase, view })
 *   api.setView(...), api.setPlaybackRate(x), api.setParticleDensity(f),
 *   api.setTreeVisible(name, on), api.setOverlay(which, on),
 *   api.setMotionMode('chew'|'swallow'|'rest'), api.dispose()
 *   window.__oral3d  diagnostics for the headless benchmark
 */

import * as THREE from 'three';
import { GLTFLoader } from '../vendor/jsm/loaders/GLTFLoader.js';
import { OrbitControls } from '../vendor/jsm/controls/OrbitControls.js';
import { RoomEnvironment } from '../vendor/jsm/environments/RoomEnvironment.js';

import { makeTissueMaterial, makeBoneMaterial, makeToothMaterial,
  makeVesselMaterial, makeGreatVesselMaterial, COLOR } from './materials.js';
import { buildVesselMesh, TREE_COLOR } from './vessels.js';
import { FlowSystem } from './flow.js';
import { OralKinematics } from './mastication.js';
import { buildMolecular, stepMolecular } from './molecular.js';
import { HUD, NARROW_PX } from './hud.js';

const SECTION_OFFSET = new THREE.Vector3(0, -900, 0);
const MOLECULAR_OFFSET = new THREE.Vector3(0, -1700, 0);

const TISSUE_OF = {
  tongue: ['tongue', { color: COLOR.tongue, grain: 2.2, roughness: 0.56 }],
  papillae_filiform: ['papilla', { color: COLOR.papilla, grain: 6.0 }],
  papillae_fungiform: ['papilla', { color: 0xd2524c, grain: 6.0 }],
  papillae_circumvallate: ['papilla', { color: 0xc45b54, grain: 4.0 }],
  papillae_foliate: ['papilla', { color: 0xc8625a, grain: 4.0 }],
  hard_palate: ['mucosa', { color: COLOR.mucosa_kerat, grain: 1.2 }],
  soft_palate: ['mucosa', { color: COLOR.mucosa_nonkerat, grain: 1.2 }],
  uvula: ['mucosa', { color: COLOR.mucosa_nonkerat, grain: 1.6 }],
  buccal_right: ['mucosa', { color: COLOR.mucosa_nonkerat, grain: 1.0 }],
  buccal_left: ['mucosa', { color: COLOR.mucosa_nonkerat, grain: 1.0 }],
  labial: ['mucosa', { color: 0xcf7f78, grain: 1.0 }],
  floor_of_mouth: ['mucosa', { color: 0xd98a82, grain: 1.0 }],
  gingiva_upper: ['mucosa', { color: COLOR.mucosa_kerat, grain: 1.4 }],
  gingiva_lower: ['mucosa', { color: COLOR.mucosa_kerat, grain: 1.4 }],
  parotid_right: ['gland', { color: COLOR.gland_serous, grain: 2.6 }],
  parotid_left: ['gland', { color: COLOR.gland_serous, grain: 2.6 }],
  submandibular_right: ['gland', { color: COLOR.gland_mixed, grain: 2.6 }],
  submandibular_left: ['gland', { color: COLOR.gland_mixed, grain: 2.6 }],
  sublingual_right: ['gland', { color: COLOR.gland_mucous, grain: 3.0 }],
  sublingual_left: ['gland', { color: COLOR.gland_mucous, grain: 3.0 }],
  masseter_right: ['muscle', { color: COLOR.muscle, grain: 2.0, opacity: 0.55 }],
  masseter_left: ['muscle', { color: COLOR.muscle, grain: 2.0, opacity: 0.55 }],
  temporalis_right: ['muscle', { color: COLOR.muscle, grain: 2.0, opacity: 0.5 }],
  temporalis_left: ['muscle', { color: COLOR.muscle, grain: 2.0, opacity: 0.5 }],
  trachea: ['airway', { color: COLOR.airway, grain: 1.0, opacity: 0.6 }],
  esophagus: ['airway', { color: 0x9a8e86, grain: 1.0, opacity: 0.7 }],
  thyroid_gland: ['gland', { color: 0xb08a6e, grain: 2.0, opacity: 0.8 }],
  heart: ['muscle', { color: 0x8c3a33, grain: 1.2, opacity: 0.55 }]
};
const BONE_PARTS = new Set(['mandible', 'midface', 'vertebrae_C1',
  'vertebrae_C2', 'vertebrae_C3']);
const VEIN_PARTS = new Set(['brachiocephalic_vein_left',
  'brachiocephalic_vein_right', 'superior_vena_cava']);
const ARTERY_PARTS = new Set(['common_carotid_artery_left',
  'common_carotid_artery_right']);
const TOOTH_PARTS = new Set(['teeth_upper', 'teeth_lower']);

export async function createOralScene (opts = {}) {
  const container = opts.container || document.body;
  const base = opts.assetBase || './assets/';
  const stage = (s) => { window.__oral3dStage = s; };

  stage('renderer:begin');
  const renderer = new THREE.WebGLRenderer({
    antialias: true, powerPreference: 'high-performance', alpha: false
  });
  const narrow0 = container.clientWidth < NARROW_PX;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, narrow0 ? 1.75 : 2));
  renderer.setSize(container.clientWidth, container.clientHeight);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.06;
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  container.appendChild(renderer.domElement);
  stage('renderer:ok');

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x070a10);
  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
  scene.environmentIntensity = 0.62;

  const camera = new THREE.PerspectiveCamera(
    40, container.clientWidth / container.clientHeight, 0.5, 20000);
  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.07;
  controls.minDistance = 8;
  controls.maxDistance = 4000;

  const key = new THREE.DirectionalLight(0xfff1e8, 2.1); key.position.set(0.9, 1.0, 1.1);
  const fill = new THREE.DirectionalLight(0x9fc4ff, 0.6); fill.position.set(-1.1, 0.3, -0.4);
  const rim = new THREE.DirectionalLight(0xffcfc0, 0.95); rim.position.set(-0.2, -0.9, -1.0);
  scene.add(key, fill, rim, new THREE.AmbientLight(0x30405a, 0.72));

  // ------------------------------------------------------------------ assets
  stage('fetch:begin');
  const jget = (f, optional = false) => fetch(base + f)
    .then((r) => (r.ok ? r.json() : (optional ? null : Promise.reject(
      new Error(f + ': HTTP ' + r.status)))))
    .catch((e) => { if (optional) return null; throw e; });
  const [vessels, flowSpec, model, expr, flowRep, vesselRep, geoRep, softRep] =
    await Promise.all([
      jget('oral_vessels.json'), jget('oral_flow.json'), jget('oral_model.json'),
      jget('oral_cavity_expression.json', true), jget('flow_report.json'),
      jget('vessel_report.json'), jget('geometry_report.json'),
      jget('oral_soft_report.json')
    ]);
  stage('fetch:ok');

  const gltf = await new GLTFLoader().loadAsync(base + 'oral.glb');
  stage('glb:ok');

  // ------------------------------------------------------------ organ groups
  const organ = new THREE.Group(); scene.add(organ);
  const staticG = new THREE.Group(); organ.add(staticG);
  // The swallow / venous chain anchors run from the neck to the heart. They are
  // real segmentation and belong on the page, but if they sit inside the group
  // the camera frames, the oral cavity ends up a thumbnail at the top of a
  // thorax. They get their own group, outside the framing box.
  const chainG = new THREE.Group(); organ.add(chainG);
  const mandibleG = new THREE.Group(); organ.add(mandibleG);
  const tongueG = new THREE.Group(); organ.add(tongueG);
  const palateG = new THREE.Group(); organ.add(palateG);
  const floorG = new THREE.Group(); organ.add(floorG);
  const muscleG = new THREE.Group(); organ.add(muscleG);
  const microG = new THREE.Group(); microG.position.copy(SECTION_OFFSET);
  scene.add(microG);
  const GROUPS = { 0: staticG, 1: mandibleG, 2: tongueG, 3: palateG,
    4: floorG, 5: mandibleG, 6: microG, 7: muscleG };
  const CHAIN_PARTS = new Set(['trachea', 'esophagus', 'thyroid_gland',
    'vertebrae_C1', 'vertebrae_C2', 'vertebrae_C3',
    'brachiocephalic_vein_left', 'brachiocephalic_vein_right',
    'superior_vena_cava', 'heart', 'common_carotid_artery_left',
    'common_carotid_artery_right']);
  const MUCOSA_SHEETS = new Set(['buccal_right', 'buccal_left', 'labial',
    'floor_of_mouth', 'gingiva_upper', 'gingiva_lower']);

  const mats = [];
  const parts = {};
  const tongueParts = [];
  let triOrgan = 0; let triMicro = 0;
  gltf.scene.traverse((o) => {
    if (!o.isMesh) return;
    const g = o.geometry;
    if (!g.getAttribute('_field1')) {
      console.warn(`[oral3d] mesh "${o.name}" lacks _field1; skipped`);
      return;
    }
    let mat;
    if (BONE_PARTS.has(o.name)) mat = makeBoneMaterial();
    else if (TOOTH_PARTS.has(o.name)) mat = makeToothMaterial();
    else if (VEIN_PARTS.has(o.name)) mat = makeGreatVesselMaterial(COLOR.vein);
    else if (ARTERY_PARTS.has(o.name)) mat = makeGreatVesselMaterial(COLOR.artery);
    else if (o.name.startsWith('micro_')) {
      mat = makeTissueMaterial('micro', {
        color: o.name.includes('acinus') ? COLOR.gland_serous
          : (o.name.includes('papilla') ? COLOR.papilla : COLOR.mucosa_nonkerat),
        grain: 0.4
      });
    } else {
      const spec = TISSUE_OF[o.name] || ['mucosa', { color: COLOR.mucosa_nonkerat }];
      mat = makeTissueMaterial(spec[0], spec[1]);
    }
    mats.push(mat);
    const mesh = new THREE.Mesh(g, mat);
    mesh.name = o.name;
    mesh.frustumCulled = false;
    const grp = Math.round(g.getAttribute('_field1').getW(0));
    if (CHAIN_PARTS.has(o.name)) {
      mat.transparent = true; mat.opacity = Math.min(mat.opacity ?? 1, 0.55);
      mat.depthWrite = false;
      chainG.add(mesh);
    } else if (MUCOSA_SHEETS.has(o.name)) {
      mat.transparent = true; mat.opacity = 0.36; mat.depthWrite = false;
      (GROUPS[grp] || staticG).add(mesh);
    } else {
      (GROUPS[grp] || staticG).add(mesh);
    }
    parts[o.name] = mesh;
    const tri = g.index ? g.index.count / 3 : g.getAttribute('position').count / 3;
    if (grp === 6) triMicro += tri; else triOrgan += tri;

    if (grp === 2) {
      const pos = g.getAttribute('position');
      const nrm = g.getAttribute('normal');
      const f1 = g.getAttribute('_field1');
      const u = new Float32Array(pos.count);
      for (let i = 0; i < pos.count; i++) u[i] = f1.getX(i);
      tongueParts.push({
        mesh,
        base: Float32Array.from(pos.array),
        n: Float32Array.from(nrm.array),
        u
      });
    }
  });
  stage('surfaces:ok');

  // ------------------------------------------------------------- vessels
  const vesselMats = {};
  const vesselMeshes = {};
  const vesselGroup = new THREE.Group(); organ.add(vesselGroup);
  let triVessels = 0;
  for (const t of vessels.trees) {
    const col = TREE_COLOR[t.name] || 0xaaaaaa;
    const m = makeVesselMaterial(col,
      t.name.includes('duct') ? { opacity: 0.94 } : {});
    vesselMats[t.name] = m; mats.push(m);
    const built = buildVesselMesh(t, {});
    const geo = built.geometry;
    const mesh = new THREE.Mesh(geo, m);
    mesh.name = 'tree_' + t.name;
    mesh.frustumCulled = false;
    vesselGroup.add(mesh);
    vesselMeshes[t.name] = mesh;
    triVessels += geo.index ? geo.index.count / 3
      : geo.getAttribute('position').count / 3;
  }
  stage('vessels:ok');

  const flow = new FlowSystem(flowSpec, narrow0 ? 180 : 320);
  vesselGroup.add(flow.points);
  stage('flow:ok');

  // --------------------------------------------------------- kinematics
  const kin = new OralKinematics(model, {
    mandibleGroup: mandibleG, tongueParts, softPalateGroup: palateG,
    floorGroup: floorG, muscleGroup: muscleG
  });
  const restCheck = kin.restStateCheck();
  stage('kinematics:ok');

  // --------------------------------------------------------- molecular
  const molecular = buildMolecular(model, expr);
  molecular.position.copy(MOLECULAR_OFFSET);
  scene.add(molecular);
  stage('molecular:ok');

  // ------------------------------------------------------------------ HUD
  const hudCanvas = document.createElement('canvas');
  hudCanvas.style.cssText = 'position:absolute;inset:0;pointer-events:none;z-index:5';
  container.appendChild(hudCanvas);
  const hud = new HUD(hudCanvas);

  const LBL = () => {
    const k = model.kinematics_frame;
    const g = model.gland_centroids;
    return [
      { text: '腮腺 parotid', pos: new THREE.Vector3().fromArray(g.parotid_left),
        color: '#d9bd92' },
      { text: '颌下腺 submandibular',
        pos: new THREE.Vector3().fromArray(g.submandibular_left), color: '#d2ab85' },
      { text: '舌下腺 sublingual',
        pos: new THREE.Vector3().fromArray(g.sublingual_left), color: '#c9a07a' },
      { text: '舌 tongue',
        pos: new THREE.Vector3().fromArray(k.tongue_axis[Math.floor(
          k.tongue_axis.length * 0.45)]), color: '#e4948c' },
      { text: '髁突 condyle', pos: new THREE.Vector3().fromArray(k.condyle_left),
        color: '#e8dcc4' },
      { text: '颏 menton', pos: new THREE.Vector3().fromArray(k.menton),
        color: '#e8dcc4' },
      { text: '悬雍垂 uvula', pos: new THREE.Vector3().fromArray(k.uvula_tip),
        color: '#d98a82' }
    ];
  };
  const labels = LBL();

  // --------------------------------------------------------------- state
  // declared before setView(), which resets the per-view render-cost window
  let rate = 1; let density = 1; let lastT = performance.now();
  let lastKinMs = -1e9; let lastKin = kin.measureKinematics();
  const overlays = { permeability: false, keratinisation: false, labels: true };
  const frameCost = [];
  const kinSamples = [];

  // --------------------------------------------------------------- views
  // frame on the ORAL region only: bone frame, teeth, tongue, palate, glands
  const frameBox = new THREE.Box3();
  for (const g of [staticG, mandibleG, tongueG, palateG, floorG]) {
    g.children.forEach((ch) => frameBox.expandByObject(ch));
  }
  const bb = frameBox;
  const centre = bb.getCenter(new THREE.Vector3());
  const radius = bb.getBoundingSphere(new THREE.Sphere()).radius;
  const VIEWS = {
    organ: { target: centre.clone(),
      pos: centre.clone().add(new THREE.Vector3(radius * 0.95, radius * 0.55,
        radius * 1.55)) },
    vessels: { target: centre.clone(),
      pos: centre.clone().add(new THREE.Vector3(-radius * 1.15, radius * 0.4,
        radius * 1.35)) },
    motion: { target: centre.clone().add(new THREE.Vector3(0, -6, 8)),
      pos: centre.clone().add(new THREE.Vector3(radius * 1.9, radius * 0.08,
        radius * 0.3)) },
    section: { target: SECTION_OFFSET.clone(),
      pos: SECTION_OFFSET.clone().add(new THREE.Vector3(0, 60, 320)) },
    molecular: { target: MOLECULAR_OFFSET.clone().add(new THREE.Vector3(0, -20, 0)),
      pos: MOLECULAR_OFFSET.clone().add(new THREE.Vector3(0, 0, 560)) }
  };

  let view = opts.view || 'organ';
  function setView (v) {
    if (!VIEWS[v]) return;
    view = v;
    const V = VIEWS[v];
    // A portrait viewport sees a much narrower horizontal field at the same
    // camera distance, so the same framing crops the organ. Dolly back by the
    // inverse aspect so the subject fits on a phone as it does on a desktop.
    const asp = Math.max(camera.aspect, 1e-3);
    const dolly = asp < 1 ? Math.min(2.2, 1 / asp) : 1;
    const dir = V.pos.clone().sub(V.target);
    camera.position.copy(V.target.clone().add(dir.multiplyScalar(dolly)));
    controls.target.copy(V.target);
    controls.update();
    organ.visible = v !== 'section' && v !== 'molecular';
    chainG.visible = (v === 'vessels' || v === 'molecular');
    frameCost.length = 0;        // per-view render cost, not a running mixture
    microG.visible = v === 'section';
    molecular.visible = v === 'molecular';
    vesselGroup.visible = (v === 'vessels' || v === 'organ');
    flow.points.visible = (v === 'vessels' || v === 'organ');
    muscleG.visible = (v === 'motion' || v === 'organ');
    if (v === 'motion') kin.setMode('chew');
  }
  setView(view);

  function setOverlay (which, on) {
    overlays[which] = !!on;
    for (const m of mats) {
      const u = m.userData.uniforms;
      if (!u) continue;
      if (u.uPermOverlay) u.uPermOverlay.value = overlays.permeability ? 0.85 : 0;
      if (u.uKeratOverlay) u.uKeratOverlay.value = overlays.keratinisation ? 0.8 : 0;
    }
  }

  function resize () {
    const w = container.clientWidth; const h = container.clientHeight;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio,
      w < NARROW_PX ? 1.75 : 2));
    renderer.setSize(w, h);
    camera.aspect = w / h; camera.updateProjectionMatrix();
    hud.resize(w, h, Math.min(window.devicePixelRatio, 2));
    if (typeof setView === 'function' && view) setView(view);
  }
  resize();
  const ro = new ResizeObserver(resize); ro.observe(container);

  const flowRows = () => {
    const pt = flowRep.per_tree;
    const order = ['lingual_artery', 'facial_artery', 'inferior_alveolar_artery',
      'venous_return', 'parotid_duct', 'submandibular_duct', 'sublingual_ducts'];
    const nm = { lingual_artery: '舌动脉', facial_artery: '面动脉',
      inferior_alveolar_artery: '下牙槽动脉', venous_return: '静脉回流→颈内静脉',
      parotid_duct: '腮腺管', submandibular_duct: '颌下腺管',
      sublingual_ducts: '舌下腺管' };
    return order.map((k) => ({
      name: nm[k],
      value: `${pt[k].v_mm_s_max.toFixed(1)} mm/s` +
        (pt[k].display_gain_applied > 1 ? ` ×${pt[k].display_gain_applied}` : ''),
      color: '#' + new THREE.Color(TREE_COLOR[k] || 0x999999).getHexString()
    }));
  };
  const rows = flowRows();

  let raf = 0; let disposed = false; let paused = false;
  function loop (now) {
    if (disposed) return;
    raf = requestAnimationFrame(loop);
    if (paused) { lastT = now; return; }
    const dt = Math.min(0.05, (now - lastT) / 1000);
    lastT = now;
    const t0 = performance.now();

    kin.update(dt);
    flow.update(dt * 1000, rate);
    if (view === 'molecular') stepMolecular(molecular, dt * rate);
    controls.update();
    renderer.render(scene, camera);

    const cost = performance.now() - t0;
    frameCost.push(cost);
    if (frameCost.length > 600) frameCost.shift();
    hud.tickFps(now);

    // measureKinematics walks world matrices; at an unbounded headless frame
    // rate calling it every frame dominates the frame budget, so it is sampled
    // on a 60 ms clock and the HUD reuses the cached value in between
    if (now - lastKinMs > 60) {
      lastKinMs = now;
      lastKin = kin.measureKinematics();
      if (kinSamples.length < 1200) kinSamples.push(lastKin);
    }
    const m = lastKin;
    const heart = model.cardiac_coupling || {};
    hud.draw({
      fps: hud.fps,
      triangles: (view === 'section' ? triMicro
        : triOrgan + (vesselGroup.visible ? triVessels : 0)),
      particlesDrawn: flow.points.visible ? (flow.drawn || flow.nParticles) : 0,
      magnification: view === 'section' ? model.micro.magnification : null,
      heart: { bpm: heart.hr_bpm || 0, pulse: flow.pulseNow,
        phase01: flow.cardiacPhase01 },
      motion: { mode: kin.mode, cycle_s: kin.cycleS,
        opening_mm: m.interincisal_opening_mm, phase01: m.phase,
        wave_u: m.tongue_wave_u },
      flowTitle: view === 'molecular'
        ? '舌下绕过肝首过 · 吞咽经门静脉入肝'
        : '实测 v = Q/A（峰值，未加增益）',
      flowRows: rows,
      note: `TotalSegmentator v2.0.1 ${model.subject} · CC-BY-4.0 · ` +
        `软组织全部为构造 · 无任何表达量→通量标定`
    });
    if (overlays.labels && (view === 'organ' || view === 'motion')) {
      hud.drawLabels(labels, camera, THREE);
    }
  }
  raf = requestAnimationFrame(loop);
  stage('loop:ok');

  const api = {
    scene, camera, renderer, controls, hud, kin, flow,
    setView,
    setPlaybackRate: (x) => { rate = x; kin.setRate(x); },
    setParticleDensity: (f) => { density = f; flow.setDensity(f); },
    setTreeVisible: (n, on) => {
      if (vesselMeshes[n]) vesselMeshes[n].visible = !!on;
      flow.setTreeEnabled(n, !!on);
    },
    setOverlay,
    setChainVisible: (on) => { chainG.visible = !!on; },
    setMotionMode: (m) => kin.setMode(m),
    setPaused: (p) => { paused = !!p; },
    measureKinematics: () => kin.measureKinematics(),
    sampleRings: (n) => kin.sampleRings(kin.t, n || 100),
    dispose: () => {
      disposed = true; cancelAnimationFrame(raf); ro.disconnect();
      renderer.dispose(); pmrem.dispose();
      container.removeChild(renderer.domElement);
      container.removeChild(hudCanvas);
    }
  };

  const gl = renderer.getContext();
  const dbg = gl.getExtension('WEBGL_debug_renderer_info');
  window.__oral3d = {
    get view () { return view; },
    get fps () { return hud.fps; },
    triangles: { organ: triOrgan, vessels: triVessels, micro: triMicro,
      total: triOrgan + triVessels + triMicro },
    glb_parts: Object.keys(parts).length,
    renderer_unmasked: dbg ? gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL) : null,
    vendor_unmasked: dbg ? gl.getParameter(dbg.UNMASKED_VENDOR_WEBGL) : null,
    gl_version: gl.getParameter(gl.VERSION),
    frameCost: () => frameCost.slice(),
    frameCostStats: () => {
      const a = frameCost.slice().sort((x, y) => x - y);
      if (!a.length) return null;
      return { n: a.length, mean: a.reduce((x, y) => x + y, 0) / a.length,
        p50: a[Math.floor(a.length * 0.5)], p95: a[Math.floor(a.length * 0.95)],
        max: a[a.length - 1] };
    },
    restCheck,
    setPaused: (p) => api.setPaused(p),
    measureKinematics: () => kin.measureKinematics(),
    kinematicHistory: () => kinSamples.slice(),
    sampleRings: (n) => kin.sampleRings(kin.t, n || 100),
    setMotionMode: (m) => kin.setMode(m),
    flowAudit: () => flow.diagnostics(),
    reports: { flow: flowRep, vessel: vesselRep, geometry: geoRep, soft: softRep },
    molecular: molecular.userData,
    hudOverflow: () => hud.overflow(),
    hudBoxes: () => hud.boxes.slice(),
    api
  };
  return api;
}
